/**
 * LLM Code Quality Evaluator
 *
 * Uses an LLM as a judge to evaluate the quality of JavaScript code
 * generated by SharedTreeSemanticAgent via tool calls.
 * Scores across dimensions like correctness, efficiency, and safety.
 */

import type { ILLMClient } from '../llm/llmClient.js';
import { parseScores } from '../llm/prompts.js';
import type { EvaluationResult } from '../types/resultTypes.js';
import type { EvaluationContext, Rubric } from './base.js';
import { BaseEvaluator, registerEvaluator } from './base.js';

const FALLBACK_SCORE = 1.5;

const CODE_QUALITY_RUBRICS: Rubric[] = [
  {
    name: 'Code Correctness',
    description:
      'Does the generated code correctly implement the requested operation? Check that it targets the right data, uses correct field names, and would produce the expected tree state changes.'
  },
  {
    name: 'Code Safety',
    description:
      'Is the code safe and defensive? Check for proper null/undefined handling, bounds checking on array operations, and absence of destructive operations that could corrupt the tree state.'
  },
  {
    name: 'Code Efficiency',
    description:
      'Is the code concise and efficient? Check that it avoids unnecessary iterations, redundant operations, or overly complex logic when a simpler approach would achieve the same result.'
  }
];

const CODE_EVAL_SYSTEM_CONTEXT = `You are evaluating JavaScript code generated by an AI agent that edits a SharedTree data structure.

The agent receives a natural language instruction and generates JavaScript code that runs against a tree context object.
The code has access to \`context.root\` (the tree root with fields like workItems, team, sprintName) and \`context.create\` (factory for creating new nodes).

You will be given:
- The user's instruction (prompt)
- The generated JavaScript code
- The output tree state after execution

Evaluate the CODE QUALITY specifically — not just whether the task was completed, but how well the code itself is written.`;

/**
 * Build the system prompt for code quality evaluation.
 */
function buildCodeSystemPrompt(rubrics: Rubric[]): string {
  const rubricList = rubrics.map((r, i) => `${i + 1}. **${r.name}**: ${r.description}`).join('\n');

  const responseFormat = rubrics
    .map((r) => `${r.name} - Score: <0-5>, Reasoning: <brief factual justification>`)
    .join('\n');

  return `${CODE_EVAL_SYSTEM_CONTEXT}

## Scoring Scale (applies to all dimensions)

- 0: No evidence — the code is empty, nonsensical, or completely wrong
- 1: Minimal — code attempts the task but has critical errors
- 2: Partial — code has the right idea but significant bugs or issues
- 3: Adequate — code works for the basic case but has notable gaps
- 4: Strong — code is correct and clean with only minor issues
- 5: Complete — code is correct, safe, efficient, and well-structured

## Dimensions to Evaluate

${rubricList}

## Response Format

Respond with exactly one line per dimension in this format:

${responseFormat}

Do not include any other text before or after the dimension lines.`;
}

/**
 * Build the user prompt with the code and context.
 */
function buildCodeUserPrompt(context: EvaluationContext): string {
  const lines: string[] = [];
  const input = context.input as Record<string, unknown> | undefined;
  const output = context.output as Record<string, unknown>;

  // Include the prompt/instruction
  if (input?.prompt) {
    lines.push('## User Instruction');
    lines.push(String(input.prompt));
    lines.push('');
  }

  // Include the generated code
  const generatedCode = output.generatedCode;
  if (generatedCode) {
    lines.push('## Generated Code');
    lines.push('```javascript');
    lines.push(String(generatedCode));
    lines.push('```');
    lines.push('');
  }

  // Include the output tree state (abbreviated)
  const treeState = output.treeState ?? output;
  lines.push('## Output Tree State (after execution)');
  lines.push(JSON.stringify(treeState, null, 2));

  return lines.join('\n');
}

class LLMCodeQualityEvaluator extends BaseEvaluator {
  readonly name = 'llm-code-quality';
  readonly description = 'LLM-as-judge evaluation of generated code quality';
  readonly isLLMBased = true;

  #injectedClient?: ILLMClient;
  #cachedClient?: ILLMClient;

  constructor(client?: ILLMClient) {
    super();
    this.#injectedClient = client;
  }

  async evaluate(context: EvaluationContext): Promise<EvaluationResult[]> {
    const startTime = Date.now();
    const configModel = context.config?.model;
    const configTemp = context.config?.temperature;
    const model = typeof configModel === 'string' ? configModel : 'gpt-4o-mini';
    const temperature = typeof configTemp === 'number' ? configTemp : 0;

    const rubrics = CODE_QUALITY_RUBRICS;

    // Check if there's generated code to evaluate
    const output = context.output as Record<string, unknown>;
    if (!output.generatedCode) {
      return rubrics.map((rubric) => ({
        evaluatorName: rubric.name,
        score: 0,
        reasoning: 'No generated code available to evaluate.',
        executionTimeMs: Date.now() - startTime
      }));
    }

    try {
      const client = await this.#getClient(model, temperature);

      const systemPrompt = buildCodeSystemPrompt(rubrics);
      const userPrompt = buildCodeUserPrompt(context);

      const response = await client.chatCompletion([
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]);

      const parsed = parseScores(response.content, rubrics);
      const executionTimeMs = Date.now() - startTime;

      if (!parsed) {
        return rubrics.map((rubric) => ({
          evaluatorName: rubric.name,
          score: FALLBACK_SCORE,
          reasoning: 'Failed to parse LLM response. Fallback score applied.',
          executionTimeMs
        }));
      }

      return rubrics.map((rubric) => ({
        evaluatorName: rubric.name,
        score: parsed[rubric.name]?.score ?? FALLBACK_SCORE,
        reasoning: parsed[rubric.name]?.reasoning ?? 'No reasoning provided.',
        executionTimeMs
      }));
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      const executionTimeMs = Date.now() - startTime;

      return rubrics.map((rubric) => ({
        evaluatorName: rubric.name,
        score: 0,
        reasoning: `Evaluation error: ${errorMessage}`,
        executionTimeMs
      }));
    }
  }

  async #getClient(model: string, temperature: number): Promise<ILLMClient> {
    if (this.#injectedClient) {
      return this.#injectedClient;
    }

    if (!this.#cachedClient) {
      const { OpenAiLLMClient } = await import('../llm/llmClient.js');
      this.#cachedClient = new OpenAiLLMClient({ model, temperature });
    }

    return this.#cachedClient;
  }
}

// Register the evaluator
export const llmCodeQualityEvaluator = registerEvaluator(new LLMCodeQualityEvaluator());
